#!/bin/bash
# Serially land Dependabot npm PRs: wait for each to merge; then update the next and arm it.
# Stops (exit 1) on a red required check or a branch that can't be updated.
cd /Users/arijit/Coding/Python/DataQ || exit 1
state() {
  gh pr view "$1" --json state,statusCheckRollup --jq '.state + " " + ([.statusCheckRollup[]|select(.conclusion=="FAILURE" and ((.name // .context)|test("Entire")|not))|(.name // .context)]|join(";"))' 2>/dev/null
}
wait_merged() {
  for i in $(seq 1 80); do
    read -r st fails <<<"$(state "$1")"
    echo "$(date +%H:%M) #$1 $st ${fails:-}"
    [ "$st" = "MERGED" ] && return 0
    [ -n "$fails" ] && return 1
    sleep 45
  done
  return 1
}
prev=$1; shift
wait_merged "$prev" || { echo "STOP: #$prev did not merge"; exit 1; }
for n in "$@"; do
  gh pr update-branch "$n" >/dev/null 2>&1 || { echo "STOP: #$n update-branch failed (conflict?)"; exit 1; }
  sleep 10
  gh pr merge "$n" --auto --squash >/dev/null 2>&1
  wait_merged "$n" || { echo "STOP: #$n did not merge"; exit 1; }
done
echo "ALL MERGED"

