# Shared data sources, locals, and the idempotent RG ensure-step.

data "azurerm_client_config" "current" {}

data "azurerm_subscription" "current" {}

# ── Idempotent RG step ─────────────────────────────────────────────────────── `az group create`
# is idempotent: it creates dataq-rg if absent and is a no-op (with the same tags) if it already
# exists.
resource "null_resource" "ensure_rg" {
  triggers = {
    rg       = var.azure_resource_group
    location = var.azure_location
  }
  provisioner "local-exec" {
    command = "az group create --name ${var.azure_resource_group} --location '${var.azure_location}' --tags project=dataq --only-show-errors --output none"
  }
}

data "azurerm_resource_group" "dataq" {
  name       = var.azure_resource_group
  depends_on = [null_resource.ensure_rg]
}

resource "random_string" "suffix" {
  length  = 6
  lower   = true
  upper   = false
  numeric = true
  special = false
}

locals {
  # All DataQ-APP resources carry purpose=dataq-app so they're trivially distinguishable from any
  # other resources sharing the group in the shared RG (see the verification query in
  # deploy/terraform/README.md).
  common_tags = {
    project = var.project_tag
    managed = "terraform"
    purpose = "dataq-app"
  }

  # Deterministic Container App FQDNs, derived from the shared environment's default domain rather
  # than each app's own ingress[0].fqdn.
  env_default_domain = data.azurerm_container_app_environment.shared.default_domain
  api_fqdn           = "dataq-app-api.internal.${local.env_default_domain}"
  frontend_fqdn      = "dataq-app-frontend.${local.env_default_domain}"
  api_internal_url   = "http://${local.api_fqdn}"
  frontend_url       = "https://${local.frontend_fqdn}"
}
# The Container Apps environment is referenced, not created: a free/trial subscription allows ONE,
# which other workloads may already use (ADR 0024).
data "azurerm_container_app_environment" "shared" {
  name                = "dataq-cae"
  resource_group_name = data.azurerm_resource_group.dataq.name

  # ── Residency assertion (G4 / #434) ──────────────────────────────────────── This environment is
  # SHARED and declared as a `data` source, so its region is whatever someone else created it in.
  lifecycle {
    postcondition {
      condition     = lower(replace(self.location, " ", "")) == lower(replace(var.azure_location, " ", ""))
      error_message = <<-EOT
        Residency mismatch (G4/#434): the shared Container Apps environment is in
        '${self.location}' but var.azure_location declares '${var.azure_location}'.
        Every Container App and Job in this stack inherits the ENVIRONMENT's region,
        so applying would place the app's compute outside the declared jurisdiction.
        There is deliberately no override for this one (unlike the shared DB's
        check): the environment's region is inherited by every Container App and
        Job here, so accepting a mismatch would relocate the whole deployment.
        Either move the workload back, or change azure_location deliberately.
      EOT
    }
  }
}
# App database — a DISTINCT `dataq` database on the SHARED Postgres Flexible Server (this
# subscription caps Flexible Servers at 1, so the app may share a server other workloads use). The app connects as the least-privilege
# `dataq_app` role (owns only `dataq`; provisioned out-of-band — see deploy/terraform/README.md).
#
# SECURITY CONSTRAINT — the single-role model is load-bearing, not just tidy. Postgres's
# RI check runs implicit casts as the REFERENCED table's OWNER (ri_triggers.c), so a role
# with CREATE TYPE/CAST + REFERENCES on another owner's table can run SQL as that owner.
# Unpatched upstream as of 2026-07-24. We are not exposed ONLY because `dataq_app` is the
# single app role — adding a second, less-trusted role to the `dataq` database is what
# would create the exposure; do not, without revisiting this (docs/progress.md guardrail).

data "azurerm_postgresql_flexible_server" "shared" {
  name                = var.shared_pg_server_name
  resource_group_name = data.azurerm_resource_group.dataq.name
}

# ── Residency assertion for the resource that actually holds the data (G4/#434) ─ This server holds
# the application's personal data (`results.sample_failures`, list-shaped `observed_value`).
check "database_residency" {
  assert {
    condition     = lower(replace(data.azurerm_postgresql_flexible_server.shared.location, " ", "")) == lower(replace(coalesce(var.shared_pg_expected_location, var.azure_location), " ", ""))
    error_message = <<-EOT
      Residency drift (G4/#434, #1465): the shared PostgreSQL server is in
      '${data.azurerm_postgresql_flexible_server.shared.location}' but
      the expected region is '${coalesce(var.shared_pg_expected_location, var.azure_location)}'.
      This server holds the application's personal data, so a move is a residency
      change even when it looks routine. Confirm the new region is in the intended
      JURISDICTION, then update the variable and the matrix in docs/site/security.md.
    EOT
  }
}

locals {
  # psycopg2 URL the backend Settings read as DATABASE_URL. sslmode=require — Flexible Server
  # enforces TLS.
  database_url = join("", [
    "postgresql+psycopg2://",
    var.app_db_user, ":", urlencode(var.app_db_password),
    "@", data.azurerm_postgresql_flexible_server.shared.fqdn, ":5432/",
    var.app_db_name, "?sslmode=require",
  ])
}
