  projects: [
    liveBaseURL
      ? { name: 'live-smoke', use: { ...devices['Desktop Chrome'] } }
      : { name: 'chromium', use: { ...devices['Desktop Chrome'] } },
    // Own testDir + baseURL, so the dev-bypass specs above are untouched by it.
    ...(docsEnabled
      ? [
          {
            name: 'docs-capture',
            testDir: './e2e-docs',
            use: {
              ...devices['Desktop Chrome'],
              baseURL: docsBaseURL,
              viewport: { width: 1440, height: 900 },
              deviceScaleFactor: 2,
              colorScheme: 'light' as const,
            },
            timeout: 90_000,
            expect: { timeout: 20_000 },
          },
        ]
      : []),
    ...(demoLane === 'capture'
      ? [
          {
            name: 'demo-capture',
            testDir: './e2e-demo',
            testMatch: 'capture.spec.ts',
            use: {
              ...devices['Desktop Chrome'],
              baseURL: process.env.E2E_DEMO_BASE_URL || baseURL,
            },
          },
        ]
      : []),
    ...(demoLane === 'smoke'
      ? [
          {
            name: 'demo-smoke',
            testDir: './e2e-demo',
            testMatch: 'smoke.spec.ts',
            use: { ...devices['Desktop Chrome'], baseURL: demoSmokeURL },
          },
        ]
      : []),
    ...(otpEnabled
      ? [
          {
            name: 'otp',
            testDir: './e2e-otp',
            use: { ...devices['Desktop Chrome'], baseURL: otpBaseURL },
            // Per-project override, `chromium` untouched: the #573/#1123 precedent
            // (a slow SHARED CI runner, not a wrong wait) applied here. Every spec
            // that calls signIn.complete() drives a REAL second api + SMTP sink
            // (scripts/e2e-otp-stack.sh) through a genuine sign-in, and #1153
            // found the fixture's own synchronization legitimately needs up to
            // ~20s (the /me response) + ~3s (render) + a close-animation wait for
            // the first-login profile-completion prompt (#1139) on a contended
            // runner — that's correct, not a bug (see fixtures.ts), so the specs'
            // 30s budget was the thing exhausting, not the waits. Root-caused via
            // three straight CI runs (30762500904, 30771559194, 30772079151) each
            // green locally and red only on the shared runner. `expect.timeout`
            // is bumped proportionally for the same reason: signin/session specs
            // lean on bare `expect(locator).toBeVisible()` for post-sign-in
            // transitions, not just `waitFor`.
            timeout: 90_000,
            expect: { timeout: 20_000 },
          },
        ]
      : []),
      - name: Playwright E2E
        working-directory: frontend
        # CI=true → Playwright starts its own Vite dev server (proxying to the
        # api on :8000) and applies forbidOnly + flaky-retries.
        env:
          VITE_API_PROXY_TARGET: http://localhost:8000
        run: pnpm e2e

      # ── Email-OTP lane (ADR 0032, #736) ────────────────────────────────── A SECOND api, because
      # the auth seam picks its mode at import time and OTP wins over dev-bypass.
      - name: Start the OTP stack (SMTP sink + otp-mode api + worker)
3:on:
4-  push:
5-    branches: [main]
6-  pull_request:
7-    # No branch filter: a stacked PR (CONTRIBUTING rule 9a) targets its parent's branch.
8-    # labeled/unlabeled: the `no-changelog` label is read by the changelog check, so adding
9-    # it must re-run CI rather than wait for a push.
